    const x = r.x + 20 + i * (r.w - 40) / (n - 1), len = lerp(r.h, r.h * 0.4, i / (n - 1));
    const yb = r.y + r.h, yt = yb - len;
    const dt = t - on[i], a = dt >= 0 ? Math.exp(-dt * 1.1) : 0, amp = dt >= 0 ? 8 * Math.exp(-dt * 3) : 0;
    ctx.save(); ctx.strokeStyle = a > 0 ? rgba(mixC(T.cream, T.led, a), 1) : 'rgba(236,229,213,0.35)'; ctx.lineWidth = 3;
    ctx.beginPath();
    for (let k = 0; k <= 30; k++) { const u = k / 30; const xx = x + amp * Math.sin(Math.PI * u) * Math.cos(dt * 2 * Math.PI * (10 + i)); k ? ctx.lineTo(xx, lerp(yt, yb, u)) : ctx.moveTo(xx, yt); }
    ctx.stroke(); ctx.restore();
    rrect(x - 6, yt - 6, 12, 12, 2); ctx.fillStyle = a > 0.05 ? T.led : T.cap; ctx.fill();
    pts.push([x, yt]);
