    let x, y;
    if (k < n - 1) { const p = prog(t, on[k], on[k + 1]); const [ax, ay] = land(k), [cx, cy] = land(k + 1); x = lerp(ax, cx, p); y = lerp(ay, cy, p) - Math.sin(Math.PI * p) * 34; }
