  const pop = E.outBack(prog(t, t0 + 0.05, t0 + 0.5), 1.8);
  ctx.save(); ctx.translate(CX, 680); ctx.scale(lerp(0.4, 1, pop), lerp(0.4, 1, pop)); ctx.rotate((1 - pop) * 0.3); ctx.translate(-CX, -680);
  drawIcon(CX, 680, 420, t, { flash: fp });
