  kinetic('Play a chord.', CX, 1270, t, { font: F.head(700, 46), size: 46, align: 'center', tIn: bt(59.3), stagger: 0.014, fill: T.cream });
  const pa = E.outBack(prog(t, bt(60), bt(60) + 0.35), 2);
  if (pa > 0) { ctx.save(); ctx.translate(CX, 1340); ctx.scale(pa, pa); capButton(-180, 0, 360, 64, 'FOR iPAD & iPHONE', { lit: true, font: F.ui(800, 24), fontSize: 24 }); ctx.restore(); }
  ctx.restore();
